package org.apache.commons.cli;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import org.apache.commons.cli.CommandLine;
import org.apache.commons.cli.Option;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CommandLine_hasOption_TriageGen2Test {

    private CommandLine commandLine;
    private Map<String, Option> optionsMap;

    @SuppressWarnings("unchecked")
    @Before
    public void setUp() throws Exception {
        commandLine = new CommandLine();

        // Since CommandLine's 'options' field is private, we use reflection 
        // to inject a map to control the internal state for testing hasOption.
        optionsMap = new HashMap<>();
        Field field = CommandLine.class.getDeclaredField("options");
        field.setAccessible(true);
        field.set(commandLine, optionsMap);
    }

    @Test
    public void testHasOption_WithExistingOption() {
        // Arrange
        String optName = "-a";
        Option option = new Option(optName, "description");
        optionsMap.put(optName, option);

        // Act
        boolean result = commandLine.hasOption(optName);

        // Assert
        assertTrue("Should return true when the option exists in the map", result);
    }






}

